    {
      "claim": "Silero‑VAD gate reduces the watcher’s CPU usage on the development workstation",
      "evidence": "DEVICE‑GENERALISATION warm‑run (5 repeats, spread < 3 %): gated watcher uses 0.23 % of a core versus ungated watcher 39.1 % of a core (ratio ≈ 170 ×). Null hypothesis: no reduction (ratio = 1)."
    },
    {
      "claim": "The previously reported 50 % banding in the empty‑room video was an artefact of an incorrect frame‑stride",
      "evidence": "EMPTY‑ROOM‑NULL results (corrected NV12 stride, 19 200 B/frame): empty‑room banded fraction = 0.0000 % (baseline). Null hypothesis: empty room shows 0 % banding. The earlier 50 % figure is retracted (see CAMERA‑FLICKER‑BANDING)."
    },
    {
      "claim": "A mouth‑localised visual signal survives head motion and is stronger when speaking than a cheek control",
      "evidence": "MOUTH‑DETECTOR results: speaking mouth region moves +0.733 sd, cheek control +0.477 sd (Δ = 0.256 sd). Null hypothesis: no difference (Δ = 0)."
    },
    {
      "claim": "A large cloud multimodal model can detect speaking from a single 160×96 greyscale frame",
      "evidence": "CLOUD‑MULTIMODAL results: sensitivity = 0.667 (8/12 speaking frames), false‑positive rate = 0.0 (0/12 silent frames). Null hypothesis: chance performance (0.5). Margin over null = +0.167."
    },
    {
      "claim": "Temporal‑median row‑band removal isolates a genuine speech‑related motion signal",
      "evidence": "TEMPORAL‑MEDIAN‑FIX results (median across repeats): occupied flip‑rate = 0.462 ± 0.03, empty‑room flip‑rate = 0.000. Null hypothesis: no signal (flip‑rate = 0). Margin = 0.462."
    },
    {
      "claim": "Fundamental‑frequency (F0) jumps cannot reliably identify speaker changes in this corpus",
      "evidence": "F0‑SPEAKER‑CHANGE results: median jump ≈ 0.3 σ, no separation between same‑speaker and different‑speaker pauses. Null hypothesis: F0 provides no discriminative power (effect = 0)."
    },
    {
      "claim": "The LLM‑director’s repeatability is limited by hosted inference nondeterminism, not by the model itself",
      "evidence": "LOCAL‑VLM‑VISION and DIRECTOR‑REPEATABILITY results: hosted GPT‑OSS‑120b shows 4 distinct headlines over 8 runs (spread = 0.619), deterministic stub shows 1 headline (spread = 0). Null hypothesis: deterministic behaviour (spread = 0)."
    }
  ],
  "unsafe_claims": [
    {
